/* eslint-disable react/prop-types */
import React, { useEffect, useState, useMemo } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate, useLocation } from 'react-router-dom';
import {
    Card,
    Stack,
    Typography,
    TablePagination,
    Popover,
    MenuItem,
    IconButton,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    Button,
    TextField,
} from '@mui/material';
import Label from '../../components/label';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import { axios } from '../../utils/axios';
import { updateUrlParams } from '../../utils/urlUtilis';
import Iconify from '../../components/iconify';
import Scrollbar from '../../components/scrollbar';
import { UserListToolbar } from '../../sections/@dashboard/user';
import { useMyContext } from '../provider';
import useResponsive from '../../hooks/useResponsive';
import TanstackTable from '../../components/tanstackMUItable/TanstackTable';
import DateFormat from '../../components/dayjsFormat/DateFormat';
import DeleteModal from '../../components/deleteModal/DeleteModal';
import TanstackTableV8 from '../../components/tanstackMUItable/tanstackTableV8';

const ViewAdvertisement = () => {
    const location = useLocation();
    const queryParams = new URLSearchParams(location.search);
    const navigate = useNavigate();
    const [opens, setOpens] = useState(false);
    const [advertisementList, setAdvertisementList] = useState([]);
    const [totalCount, setTotalCount] = useState(0);
    const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
    const [search, setsearch] = useState(queryParams.get('search') || '');
    const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
    const { i18 } = useMyContext();
    const isMobile = useResponsive('down', 'sm')
    const [declineModalOpen, setDeclineModalOpen] = useState(false);
    const [declineReason, setDeclineReason] = useState('');
    const [selectedAdId, setSelectedAdId] = useState(null);
    const [filters, setFilters] = useState({ });
    const [isLoading, setIsLoading] = useState(true);


    const fetchData = async () => {
        setIsLoading(true);
        try {
            let url = `module/ads/all?_page=${page}&_limit=${rowsPerPage}`

            // if (search) {
            //     url += `&search=${search}`;
            //     setPage(1);
            // }

            if (search) url += `&search=${search}`;
            Object.entries(filters).forEach(([key, value]) => {
                if (value) url += `&${key}=${value}`;
            });

            const response = await axios.get(url);
            if (response.status === 200) {
                setAdvertisementList(response?.data?.data?.adsData);
                setTotalCount(response?.data?.data?.totalCount ? response?.data?.data?.totalCount : 0);
            }
        } catch (error) {
            console.error(error);
        } finally {
            setIsLoading(false);
        }
    }

    useEffect(() => {
        fetchData();
    }, [page, rowsPerPage, search, filters]);


    useEffect(() => {
        updateUrlParams({ page, limit: rowsPerPage });
    }, [page, rowsPerPage, search]);

    const handleChangePage = (event, newPage) => {
        setPage(newPage + 1);
    };

    const handleChangeRowsPerPage = (event) => {
        const newLimit = parseInt(event.target.value, 10);
        setRowsPerPage(newLimit);
        setPage(1);
    };

    const handleFilterByName = (event) => {
        const filterValue = event.target.value;
        setsearch(filterValue);
        queryParams.set('search', filterValue);
        window.history.pushState(null, '', `?${queryParams.toString()}`);
    };

    const handleDeclineClose = () => {
        setDeclineModalOpen(false);
        setDeclineReason('');
        setSelectedAdId(null);
    };

    const handleStatusUpdate = async (id, status, reason = '') => {
        try {
            const urlencoded = new URLSearchParams();
            urlencoded.append("status", status);
            if (reason) {
                urlencoded.append("reason", reason);
            }

            const response = await axios.put(`module/ads/status/${id}`, urlencoded);
            if (response?.status === 200) {
                GenerateToastConfig(response.data.message, 'success');
                fetchData();
            }
        } catch (error) {
            console.error(error.message);
        }
    };

    const deleteAdvertisment = async() => {
        console.log("I'm in buddy");
    }

    const ActionComponent = (cell) => {
        const value = cell?.getValue();
        const original = cell?.row?.original;
        const [anchorEl, setAnchorEl] = useState(null);
        const [menuRowId, setMenuRowId] = useState(null);

        const handleActionMenu = (event, rowId) => {
            setAnchorEl(event.currentTarget);
            setMenuRowId(rowId);
        };

        const handleActionMenuClose = () => {
            setAnchorEl(null);
            setMenuRowId(null);
        };

        const handleDeclineOpen = (id) => {
            setSelectedAdId(id);
            setDeclineModalOpen(true);
        };

        const deletemodel = () => {
            setOpens(true);
            setAnchorEl(null);
            setMenuRowId(null);
        };

        const handleEditAdvertisement = (id, userId) => {
            console.log(userId);
            navigate(`/dashboard/editAdvertisement?adsIds=${id}`, {state: { userIds: userId}})
        }

        
          
        return (
            <>
                <IconButton
                    sx={{
                        width: '37px',
                        height: '37px',
                        background: '#EBEBEB',
                        color: 'black',
                        borderRadius: '50%',
                    }}
                    onClick={(event) => handleActionMenu(event, value)}
                >
                    <Iconify icon="mdi:dots-horizontal" />
                </IconButton>
                <Popover
                    anchorEl={anchorEl}
                    open={Boolean(anchorEl) && menuRowId === value}
                    onClose={handleActionMenuClose}
                    anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
                    transformOrigin={{ vertical: 'top', horizontal: 'right' }}
                    PaperProps={{
                        sx: { width: 140 },
                    }}
                >
                    {/* {value?.status === "approve" &&
                        <MenuItem>
                            <Iconify icon={'carbon:view'} sx={{ mr: 2 }} /> View
                        </MenuItem>
                    } */}

                    <MenuItem onClick={() => handleEditAdvertisement(original?._id, original?.userId)}>
                        <Iconify icon={'carbon:edit'} sx={{ mr: 2 }} /> Edit
                    </MenuItem>

                    {(original?.status === "publish" || original?.status === "decline") && (
                        <MenuItem onClick={() => handleStatusUpdate(original?._id, "approve")}>
                            <Iconify icon={'mdi:approve'} sx={{ mr: 2 }} /> Approve
                        </MenuItem>
                    )}

                    {original?.status === "approve" && (
                        <MenuItem onClick={() => handleDeclineOpen(original?._id)}>
                            <Iconify icon={'mdi:close-circle-outline'} sx={{ mr: 2 }} /> Decline
                        </MenuItem>
                    )}

                    <MenuItem onClick={() => deletemodel(original?._id)}>
                        <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} /> Delete
                    </MenuItem>

                </Popover>

            </>
        );
    }

    const columns = [
        {
            header: i18?.ACCOUNTSTITLE?.ADVERTISEMENTNAME || 'Name',
            id: 'name',
            accessorKey: 'name',
            showFilter: false, 
            cell: ({ row }) => <span>{row?.original?.name || "---"}</span>
        },
        {
            header: i18?.ACCOUNTSTITLE?.ADVERTISEMENTDESC || 'Description',
            id: 'desc',
            accessorKey: 'desc',
            cell: ({ row }) => <span>{row?.original?.desc || "---"}</span>
        },
        {
            header: i18?.ACCOUNTSTITLE?.USERNAME || 'Username',
            id: 'username',
            accessorKey: 'username',
            showFilter: false, 
            cell: ({ row }) => <span>{row?.original?.userData?.firstname && row?.original?.userData?.lastname
                ? `${row?.original?.userData?.firstname} ${row?.original?.userData?.lastname}`
                : "---"}</span>
        },
        {
            header: i18?.ACCOUNTSTITLE?.COUNTRY || 'Country',
            id: 'country',
            accessorKey: 'country',
            cell: ({ row }) => <span>{row?.original?.address?.country || "---"}</span>
        }, {
            header: i18?.ACCOUNTSTITLE?.STATE || 'State',
            id: 'state',
            accessorKey: 'state',
            cell: ({ row }) => <span>{row?.original?.address?.state || "---"}</span>
        },
        {
            header: i18?.ACCOUNTSTITLE?.CITY || 'City',
            id: 'city',
            accessorKey: 'city',
            cell: ({ row }) => <span>{row?.original?.address?.city || "---"}</span>
        },
        {
            header: i18?.ACCOUNTSTITLE?.PUBLISH || 'Publish',
            id: 'publish',
            accessorKey: 'publish',
            showFilter: false,
            cell: ({ row: { original } }) => (
                <Label color={original?.status === 'pending' ? 'error' : 'success'}>
                    {original?.status === 'pending' ? 'No' : 'Yes'}
                </Label>
            )
        },
        {
            header: i18?.ACCOUNTSTITLE?.STATUS || 'Status',
            id: 'status',
            accessorKey: 'status',
            showFilter: false,
            cell: ({ row: { original } }) =>
                <Label color={original?.status === 'approve' ? 'success' : 'warning'}>{original?.status}</Label>
        },
        {
            header: i18?.ACCOUNTSTITLE?.ACTION || "Action",
            id: "action",
            accessorKey: "_id",
            cell: ActionComponent,
        },
    ];

    // const columns = useMemo(() => COLUMNS, []);
    // // console.log("columns55", columns);
    // // const data = React.useMemo(() => userList || [], [userList]);
    // // console.log("adminList111", data);
    // const data = React.useMemo(() => advertisementList?.map((advertisementData) => {
    //     console.log(advertisementData);
    //     return {
    //         name: advertisementData?.name,
    //         desc: advertisementData?.desc,
    //         username: `${advertisementData?.userData?.firstname} ${advertisementData?.userData?.lastname}`,
    //         country: advertisementData?.address?.country,
    //         state: advertisementData?.address?.state,
    //         city: advertisementData?.address?.city,
    //         status: advertisementData?.status,
    //         publish: advertisementData?.publish,
    //         action: advertisementData,
    //     }
    // }), [advertisementList])

    const handleFilterChange = (filterKey, value) => {
        setFilters((prev) => ({ ...prev, [filterKey]: value }));
        setPage(1);
      };

    return (
        <>
            <Helmet>
                <title> view advertisement | Admin panel </title>
            </Helmet>
            {isMobile && <Stack direction='row' alignItems="center" style={{ marginBottom: "30px" }} justifyContent="space-between">
                <Typography variant="h4" gutterBottom>
                    {i18?.ACCOUNTSTITLE?.ADVERTISEMENTLIST || "Advertisement List"}
                </Typography>
            </Stack>}
            {!isMobile && <Stack direction='row' alignItems="center" justifyContent="space-between">
                <Stack direction={'row'} alignItems="center" >
                    <Typography variant="h4" gutterBottom>
                        {i18?.ACCOUNTSTITLE?.ADVERTISEMENTLIST || "Advertisement List"}
                    </Typography>
                </Stack>
                <Stack direction='row' alignItems="center" >
                    <UserListToolbar
                        // numSelected={selected.length}
                        // filterName={filterName}
                        onFilterName={handleFilterByName}
                        search={search}
                        setsearch={setsearch}
                    />
                </Stack>
            </Stack>}

            <Card sx={{ padding: '0px 0px', margin: '0px 0px', overflowX: 'auto' }}>
                {isMobile && <UserListToolbar
                    // numSelected={selected.length}
                    // filterName={filterName}
                    onFilterName={handleFilterByName}
                    search={search}
                    setsearch={setsearch}
                />}

                <Scrollbar>
                    {/* <TanstackTable data={data} columns={columns} /> */}
                    <TanstackTableV8
                        data={advertisementList}
                        columns={columns}
                        filters={filters}
                        isLoading={isLoading}
                        onFilterChange={handleFilterChange}
                    />
                </Scrollbar>
            </Card>

            <TablePagination
                rowsPerPageOptions={[5, 10, 25]}
                component="div"
                count={totalCount || 0}
                rowsPerPage={rowsPerPage}
                page={page - 1}
                onPageChange={handleChangePage}
                onRowsPerPageChange={handleChangeRowsPerPage}
                sx={{
                    '.MuiTablePagination-selectLabel': {
                        marginTop: '12px',
                    },
                    '.MuiTablePagination-displayedRows': {
                        marginTop: '12px',
                    },
                    '.MuiTablePagination-actions': {
                        marginBottom: '6px',
                    }
                }}
            />

            <Dialog
                open={declineModalOpen}
                onClose={handleDeclineClose}
                maxWidth="xs"
                fullWidth
            >
                <DialogTitle>Reason for Decline</DialogTitle>
                <DialogContent>
                    <TextField
                        autoFocus
                        margin="dense"
                        id="declineReason"
                        label="Reason"
                        type="text"
                        fullWidth
                        variant="standard"
                        value={declineReason}
                        onChange={(e) => setDeclineReason(e.target.value)}
                    />
                </DialogContent>
                <DialogActions>
                    <Button onClick={handleDeclineClose}>Cancel</Button>
                    <Button disabled={!declineReason} onClick={() => {
                        handleStatusUpdate(selectedAdId, "decline", declineReason);
                        handleDeclineClose();
                    }}>Submit</Button>
                </DialogActions>
            </Dialog>

            <DeleteModal 
                isDeleteOpen={opens}
                handleClose={() => setOpens(false)}
                handleDelete={deleteAdvertisment}
            />
        </>
    )
}

export default ViewAdvertisement
